import json
from pathlib import Path

# First, let's examine the actual structure of a Scandinavian task result
cache_dir = Path("/root/.cache/mteb/results/results")
scandinavian_tasks = ['DanFeverRetrieval', 'NorQuadRetrieval', 'SNLRetrieval', 'SwednRetrieval']

found_file = None
for model_dir in cache_dir.iterdir():
    if not model_dir.is_dir():
        continue
    for sub_dir in model_dir.iterdir():
        if not sub_dir.is_dir():
            continue
        for task_name in scandinavian_tasks:
            task_file = sub_dir / f"{task_name}.json"
            if task_file.exists():
                found_file = task_file
                break
    if found_file:
        break

if found_file:
    print(f"Examining file: {found_file}")
    with open(found_file) as f:
        data = json.load(f)

    print(f"Structure type: {type(data)}")
    if isinstance(data, dict):
        print(f"Top-level keys: {list(data.keys())}")
        if 'scores' in data:
            print(f"Scores type: {type(data['scores'])}")
            print(f"First score: {data['scores'][:2] if isinstance(data['scores'], list) else data['scores']}")
    elif isinstance(data, list):
        print(f"List with {len(data)} items")
        if data:
            print(f"First item: {data[0]}")
else:
    print("No Scandinavian task file found")
